6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":2707,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 9.20\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T55b,The word trai-vidyāḥ refers to the three Vedas – Sāma, Yajur and Ṛg. A brāhmaṇa who has studied these three Vedas is called a tri-vedī. Anyone who is very much attached to knowledge derived from these three Vedas is respected in society. Unfortunately, there are many great scholars of the Vedas who do not know the ultimate purport of studying them. Therefore Kṛṣṇa herein declares Himself to be the ultimate goal for the tri-vedīs. Actual tri-vedīs take shelter under the lotus feet of Kṛṣṇa and engage in pure devotional service to satisfy the Lord. Devotional service begins with the chanting of the Hare Kṛṣṇa mantra and side by side trying to understand Kṛṣṇa in truth. Unfortunately those who are simply official students of the Vedas become more interested in offering sacrifices to the different demigods like Indra and Candra. By such endeavor, the worshipers of different demigods are certainly purified of the contamination of the lower qualities of nature and are thereby elevated to the higher planetary systems or heavenly planets known as Maharloka, Janaloka, Tapoloka, etc. Once situated on those higher planetary systems, one can satisfy his senses hundreds of thousands of times better than on this planet."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":2707,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"20\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 20\",\"advanced_view_url_path\":\"/en/library/bg/9/advanced-view/#bb2398\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/9/20/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/9/20/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/9/20/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/9/20/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"enabled\":true,\"url_path\":\"/en/library/bg/9/20/\"},{\"display_name\":\"Español (Spanish)\",\"language_code\":\"es\",\"enabled\":true,\"url_path\":\"/es/library/bg/9/20/\"},{\"display_name\":\"Eesti keel (Estonian)\",\"language_code\":\"et\",\"enabled\":true,\"url_path\":\"/et/library/bg/9/20/\"},{\"display_name\":\"Suomen kieli (Finnish)\",\"language_code\":\"fi\",\"enabled\":false,\"url_path\":\"/fi