ते पुण्यमासाद्य सुरेन्द्रलोक-
मश्न‍‍न्ति दिव्यान्दिवि देवभोगान् ॥ २० ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2709,\"bb\":2399,\"url_path\":\"/en/library/bg/9/20/b2399/\",\"body_value\":\"trai-vidyā māṁ soma-pāḥ pūta-pāpā
yajñair iṣṭvā svar-gatiṁ prārthayante
te puṇyam āsādya surendra-lokam
aśnanti divyān divi deva-bhogān\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2710,\"bb\":2400,\"url_path\":\"/en/library/bg/9/20/b2400/\",\"shadow_value\":\"trai-vidyāḥ – the knowers of the three Vedas; mām – Me; soma-pāḥ – drinkers of soma juice; pūta – purified; pāpāḥ – of sins; yajñaiḥ – with sacrifices; iṣṭvā – worshiping; svaḥ-gatim – passage to heaven; prārthayante – pray for; te – they; puṇyam – pious; āsādya – attaining; sura-indra – of Indra; lokam – the world; aśnanti – enjoy; divyān – celestial; divi – in heaven; deva-bhogān – the pleasures of the gods.\",\"word_for_word_value\":[{\"word\":\"trai-vidyāḥ\",\"translation\":\"the knowers of the three Vedas\"},{\"word\":\"mām\",\"translation\":\"Me\"},{\"word\":\"soma-pāḥ\",\"translation\":\"drinkers of soma juice\"},{\"word\":\"pūta\",\"translation\":\"purified\"},{\"word\":\"pāpāḥ\",\"translation\":\"of sins\"},{\"word\":\"yajñaiḥ\",\"translation\":\"with sacrifices\"},{\"word\":\"iṣṭvā\",\"translation\":\"worshiping\"},{\"word\":\"svaḥ-gatim\",\"translation\":\"passage to heaven\"},{\"word\":\"prārthayante\",\"translation\":\"pray for\"},{\"word\":\"te\",\"translation\":\"they\"},{\"word\":\"puṇyam\",\"translation\":\"pious\"},{\"word\":\"āsādya\",\"translation\":\"attaining\"},{\"word\":\"sura-indra\",\"translation\":\"of Indra\"},{\"word\":\"lokam\",\"translation\":\"the world\"},{\"word\":\"aśnanti\",\"translation\":\"enjoy\"},{\"word\":\"divyān\",\"translation\":\"celestial\"},{\"word\":\"divi\",\"translation\":\"in heaven\"},{\"word\":\"deva-bhogān\",\"translation\":\"the pleasures of the gods\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2711,\"bb\":2401,\"url_path\":\"/en/library/bg/9/20/b2401/\",\"body_value\":\"Those who study the Vedas and drink the soma juice, seeking the heavenly planets, worship Me indirectly. Purified of sinful reactions, they take birth on the pious, heavenly planet of Indra, where they enjoy godly delights.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2712,\"bb\":2402,\"url_path\":\"/en/library/bg/9/20/b2402/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 9.20\",\"medium_title\":\"Bhagavad-gītā As It Is 9.20\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"B