aśnanti divyān divi deva-bhogān\"}}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"2707-synonyms,2707-synonyms\",{\"className\":\"av-synonyms\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Synonyms\"}],[[\"$\",\"$L2a\",\"child-2710\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:2:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-justify\",\"children\":[[\"$\",\"span\",\"wfwundefined-0\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-trai\",{\"href\":\"/en/search/synonyms/?original=trai\",\"children\":[\"$\",\"em\",null,{\"children\":\"trai\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-vidyāḥ\",{\"href\":\"/en/search/synonyms/?original=vidyāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"vidyāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"the knowers of the three Vedas\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-1\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-2\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-soma\",{\"href\":\"/en/search/synonyms/?original=soma\",\"children\":[\"$\",\"em\",null,{\"children\":\"soma\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-pāḥ\",{\"href\":\"/en/search/synonyms/?original=pāḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"pāḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"drinkers of soma juice\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",